import {LitElement, html, render} from "lit";
import {atomState} from "/Users/peterkloss/Dev/ACMElabs/design-system/src/shared/atom-state.ts";
const results:any[]=[];
const checks=(name:string,actual:any,expected:any)=>results.push({name,actual,expected,pass:JSON.stringify(actual)===JSON.stringify(expected)});
const cssText=(entries:[string,unknown][])=>entries.filter(([,v])=>v!=null).map(([k,v])=>k.replace(/[A-Z]/g,c=>"-"+c.toLowerCase())+":"+v).join(";");
class Individual extends LitElement {
 static properties={padding:{noAccessor:true},paddingInline:{attribute:"padding-inline",noAccessor:true}};
 @atomState() declare padding:string|undefined;
 @atomState() declare paddingInline:string|undefined;
 @atomState() declarationOrder:string[]=[];
 record(name:string,value:unknown){if(value==null)this.declarationOrder=this.declarationOrder.filter(k=>k!==name);else if(!this.declarationOrder.includes(name))this.declarationOrder=[...this.declarationOrder,name];}
 render(){return html`<div id="content" style=${cssText(this.declarationOrder.map(k=>[k,(this as any)[k]]))}>Individual properties</div>`;}
}
for(const key of ["padding","paddingInline"]){const d=Object.getOwnPropertyDescriptor(Individual.prototype,key)!;Object.defineProperty(Individual.prototype,key,{...d,set(value){(this as Individual).record(key,value);d.set!.call(this,value);}});}

class Capturing extends LitElement {
 static get observedAttributes(){return [...super.observedAttributes,"padding","padding-inline"];}
 @atomState() declare padding:string|undefined;
 @atomState() declare paddingInline:string|undefined;
 @atomState() declarationOrder:string[]=[];
 private initialAttributes=new Map<string,string>();
 constructor(){
  super();
  const keys=Object.keys(this).filter(k=>["padding","paddingInline"].includes(k));
  const properties=keys.map(k=>[k,(this as any)[k]] as const);
  for(const key of keys)delete (this as any)[key];
  for(const a of [...this.attributes])if(["padding","padding-inline"].includes(a.name)){
    this.initialAttributes.set(a.name,a.value);
    (this as any)[a.name==="padding-inline"?"paddingInline":"padding"]=a.value;
  }
  for(const [key,value] of properties)(this as any)[key]=value;
 }
 record(name:string,value:unknown){if(value==null)this.declarationOrder=this.declarationOrder.filter(k=>k!==name);else if(!this.declarationOrder.includes(name))this.declarationOrder=[...this.declarationOrder,name];}
 attributeChangedCallback(name:string,oldValue:string|null,newValue:string|null){
  if(!["padding","padding-inline"].includes(name)){super.attributeChangedCallback(name,oldValue,newValue);return;}
  if(oldValue===null&&this.initialAttributes.get(name)===newValue){this.initialAttributes.delete(name);return;}
  (this as any)[name==="padding-inline"?"paddingInline":"padding"]=newValue??undefined;
 }
 render(){return html`<div id="content" style=${cssText(this.declarationOrder.map(k=>[k,(this as any)[k]]))}>Public capture candidate</div>`;}
}
for(const key of ["padding","paddingInline"]){const d=Object.getOwnPropertyDescriptor(Capturing.prototype,key)!;Object.defineProperty(Capturing.prototype,key,{...d,set(value){(this as Capturing).record(key,value);d.set!.call(this,value);}});}

class Ordered extends LitElement {
 static properties={styleValues:{type:Object,attribute:"style-values",noAccessor:true}};
 @atomState() declare styleValues:Record<string,string>|undefined;
 render(){return html`<div id="content" style=${cssText(Object.entries(this.styleValues??{}))}>Ordered input</div>`;}
}
const mount=async(el:any)=>{document.body.append(el);await el.updateComplete;return el};
const edges=(el:any)=>{const s=getComputedStyle(el.shadowRoot.querySelector("#content"));return [s.paddingTop,s.paddingRight,s.paddingBottom,s.paddingLeft]};
try {
 const early:any=document.createElement("order-individual-early");
 early.paddingInline="8px";early.padding="16px";
 const earlyOwn=Object.keys(early).filter(k=>["padding","paddingInline"].includes(k));
 document.body.append(early);customElements.define("order-individual-early",class extends Individual{});await early.updateComplete;
 checks("pre-definition individual authored own-key order",earlyOwn,["paddingInline","padding"]);
 checks("pre-definition individual setter order",early.declarationOrder,["paddingInline","padding"]);
 checks("pre-definition individual expected declaration result",edges(early),["16px","16px","16px","16px"]);
 customElements.define("order-individual-ready",class extends Individual{});
 const ready:any=document.createElement("order-individual-ready");ready.paddingInline="8px";ready.padding="16px";await mount(ready);
 checks("post-definition individual order",ready.declarationOrder,["paddingInline","padding"]);
 checks("post-definition individual result",edges(ready),["16px","16px","16px","16px"]);
 ready.paddingInline="4px";await ready.updateComplete;
 checks("later value update keeps position in fixture",ready.declarationOrder,["paddingInline","padding"]);
 checks("later value update does not move declaration",edges(ready),["16px","16px","16px","16px"]);
 const attrs:any=document.createElement("order-individual-attributes");attrs.setAttribute("padding-inline","8px");attrs.setAttribute("padding","16px");document.body.append(attrs);customElements.define("order-individual-attributes",class extends Individual{});await attrs.updateComplete;
 checks("initial HTML attribute order",attrs.declarationOrder,["paddingInline","padding"]);
 checks("initial HTML attribute result",edges(attrs),["16px","16px","16px","16px"]);
 const ordered:any=document.createElement("order-object-early");const initial={paddingInline:"8px",padding:"16px"};ordered.styleValues=initial;document.body.append(ordered);customElements.define("order-object-early",class extends Ordered{});await ordered.updateComplete;
 checks("pre-definition object identity preserved",ordered.styleValues===initial,true);
 checks("pre-definition object order preserved",Object.keys(ordered.styleValues),["paddingInline","padding"]);
 checks("pre-definition object result",edges(ordered),["16px","16px","16px","16px"]);
 ordered.styleValues={padding:"16px",paddingInline:"8px"};await ordered.updateComplete;
 checks("object replacement can reorder same values",edges(ordered),["16px","8px","16px","8px"]);
 ordered.styleValues={...ordered.styleValues,padding:"20px"};await ordered.updateComplete;
 checks("object value update keeps key position",Object.keys(ordered.styleValues),["padding","paddingInline"]);
 checks("object value update result",edges(ordered),["20px","8px","20px","8px"]);
 ordered.setAttribute("style-values",'{"paddingInline":"4px","padding":"12px"}');await ordered.updateComplete;
 checks("JSON attribute order",Object.keys(ordered.styleValues),["paddingInline","padding"]);
 checks("JSON attribute result",edges(ordered),["12px","12px","12px","12px"]);
 const container=document.createElement("div");document.body.append(container);
 render(html`<order-individual-ready .paddingInline=${"8px"} .padding=${"16px"}></order-individual-ready>`,container);const bound:any=container.firstElementChild;await bound.updateComplete;
 checks("registered Lit binding order",bound.declarationOrder,["paddingInline","padding"]);
 checks("registered Lit binding result",edges(bound),["16px","16px","16px","16px"]);
 const lateContainer=document.createElement("div");document.body.append(lateContainer);
 render(html`<order-lit-before-definition .paddingInline=${"8px"} .padding=${"16px"}></order-lit-before-definition>`,lateContainer);
 customElements.define("order-lit-before-definition",class extends Individual{});const late:any=lateContainer.firstElementChild;await late.updateComplete;
 checks("Lit binding before registration order",late.declarationOrder,["paddingInline","padding"]);
 checks("Lit binding before registration result",edges(late),["16px","16px","16px","16px"]);

 const captured:any=document.createElement("order-captured-early");
 captured.paddingInline="8px";captured.padding="16px";document.body.append(captured);
 customElements.define("order-captured-early",class extends Capturing{});await captured.updateComplete;
 checks("capture candidate preserves pre-definition order",captured.declarationOrder,["paddingInline","padding"]);
 checks("capture candidate preserves pre-definition result",edges(captured),["16px","16px","16px","16px"]);
 captured.paddingInline="4px";await captured.updateComplete;
 checks("capture candidate update retains position",captured.declarationOrder,["paddingInline","padding"]);
 checks("capture candidate update result",edges(captured),["16px","16px","16px","16px"]);
 const capturedAttrs:any=document.createElement("order-captured-attrs");
 capturedAttrs.setAttribute("padding-inline","8px");capturedAttrs.setAttribute("padding","16px");document.body.append(capturedAttrs);
 customElements.define("order-captured-attrs",class extends Capturing{});await capturedAttrs.updateComplete;
 checks("capture candidate HTML order",capturedAttrs.declarationOrder,["paddingInline","padding"]);
 checks("capture candidate HTML result",edges(capturedAttrs),["16px","16px","16px","16px"]);
 capturedAttrs.removeAttribute("padding-inline");await capturedAttrs.updateComplete;
 checks("capture candidate removal",capturedAttrs.declarationOrder,["padding"]);
 capturedAttrs.setAttribute("padding-inline","4px");await capturedAttrs.updateComplete;
 checks("capture candidate re-add appends",capturedAttrs.declarationOrder,["padding","paddingInline"]);
 checks("capture candidate re-add result",edges(capturedAttrs),["16px","4px","16px","4px"]);
 const detached:any=document.createElement("order-captured-detached");
 detached.paddingInline="8px";detached.padding="16px";
 customElements.define("order-captured-detached",class extends Capturing{});customElements.upgrade(detached);
 checks("capture candidate detached upgrade synchronous value",detached.padding,"16px");
 await mount(detached);checks("capture candidate detached upgrade order",detached.declarationOrder,["paddingInline","padding"]);
 checks("capture candidate detached upgrade result",edges(detached),["16px","16px","16px","16px"]);
 const mixed:any=document.createElement("order-captured-mixed");
 mixed.setAttribute("padding-inline","2px");mixed.setAttribute("padding","3px");
 mixed.paddingInline="8px";mixed.padding="16px";
 document.body.append(mixed);customElements.define("order-captured-mixed",class extends Capturing{});await mixed.updateComplete;
 checks("capture candidate pre-definition property values override initial attributes",edges(mixed),["16px","16px","16px","16px"]);
 const captureContainer=document.createElement("div");document.body.append(captureContainer);
 render(html`<order-captured-lit .paddingInline=${"8px"} .padding=${"16px"}></order-captured-lit>`,captureContainer);
 customElements.define("order-captured-lit",class extends Capturing{});const capturedLit:any=captureContainer.firstElementChild;await capturedLit.updateComplete;
 checks("capture candidate early Lit binding order",capturedLit.declarationOrder,["paddingInline","padding"]);
 checks("capture candidate early Lit binding result",edges(capturedLit),["16px","16px","16px","16px"]);

 (window as any).__orderProbe={done:true,userAgent:navigator.userAgent,results,passed:results.filter(x=>x.pass).length,total:results.length};
 document.querySelector("#status")!.textContent="Probe complete";
} catch(error){(window as any).__orderProbe={done:true,error:String(error),stack:(error as Error).stack,results};document.querySelector("#status")!.textContent="Probe failed";}

