import ts from "typescript";

const root="/Users/peterkloss/Dev/ACMElabs/design-system";
const entry=(await Bun.file("notes/alignment/evidence/declaration-order-probe-2026-09-20.json").json()).entrySource;
const built=await Bun.build({entrypoints:["order-probe-entry"],target:"browser",format:"esm",write:false,define:{"process.env.NODE_ENV":JSON.stringify("development")},plugins:[{name:"in-memory-probe",setup(build){build.onResolve({filter:/^order-probe-entry$/},()=>({path:"entry",namespace:"probe"}));build.onResolve({filter:/.*/,namespace:"probe"},args=>({path:Bun.resolveSync(args.path,root),namespace:"file"}));build.onLoad({filter:/.*/,namespace:"probe"},()=>({contents:ts.transpileModule(entry,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext,experimentalDecorators:true,useDefineForClassFields:false}}).outputText,loader:"js"}));}}]});
if(!built.success){console.log(built.logs);process.exit(1);}
